// External stand-in for Lokalise native automations, for six projects that cannot have
// one because the account is at 130/150 locale-pair automations.
// Order mirrors Lokalise exactly: TM 100% exact-source match first -> 100TM status.
// Only on a miss does the string go to AI generation -> AI_TO_REVIEW status.
const DRY_RUN = false;          // set true to plan without writing
const MAX_UNITS_PER_FIRE = 50;  // safety cap per webhook fire
const MODEL = 'gpt-4o';
const TM_TTL_MS = 6 * 60 * 60 * 1000;
const GLOSSARY_PID = '46552447679363c70f7ef8.58193285';

// status ids verified live 2026-09-07; Unicopy's TM status is titled "TM matches", not 100TM
const PROJECTS = {
  '14240418673f52ae29a007.74392007': { name: 'Mobitrace',                   tm: 29166, ai: 29167 },
  '9274956467e3e224807498.79791832': { name: 'Mobitrace - backend/emails',  tm: 29469, ai: 29470 },
  '50011170688b3050b0a7f8.40995136': { name: 'My Image - Backend',          tm: 29445, ai: 29446 },
  '35679002689c4f3ba6dd50.31739712': { name: 'Unicopy',                     tm: 29170, ai: 29467 },
  '1600517668d38be7f36ba4.51132642': { name: 'Unicopy (backend)',           tm: 29172, ai: 29468 },
  '4780438967fe077b4e6484.83742970': { name: 'WAPP',                        tm: 29313, ai: 29314 }
};

// Norwegian is 760 in Mobitrace and My Image - Backend but 759 in Mobitrace - backend/emails.
// Never share a language-id map across projects; these are read from /languages per project.
const LANGS = {
  '14240418673f52ae29a007.74392007': { hr:793, cs:765, da:767, nl:737, fr:673, de:666, el:761, id:757, it:734, ko:733, ms:749, no:760, pl:748, pt:708, ro:770, sk:799, es:1056, sv:754, th:753, tr:744, uk:769, vi:774 },
  '9274956467e3e224807498.79791832': { hr:793, cs:765, da:767, nl:737, fr:673, de:666, el:761, id:757, it:734, ko:733, ms:749, no:759, pl:748, pt:708, ro:770, sk:799, es:1056, sv:754, th:753, tr:744, uk:769, vi:774 },
  '50011170688b3050b0a7f8.40995136': { da:767, nl:737, fr:673, de:666, id:757, it:734, ko:733, ms:749, no:760, pl:748, pt:708, ro:770, es:1056, sv:754, th:753, tr:744, uk:769, vi:774 },
  '35679002689c4f3ba6dd50.31739712': { es:1056 },
  '1600517668d38be7f36ba4.51132642': { es:1056 },
  '4780438967fe077b4e6484.83742970': { nl:737, fr:673, de:666, it:734, pt:708, es:1056 }
};

// Distilled from the style guide documents. Register is the field most often got wrong,
// so it leads every block.
const GUIDES = {
  cs: 'Register: formal 2nd-person plural (vykani). Concise, readable, friendly but authoritative; short clear sentences. Gender-neutral where possible, otherwise grammatical neutral masculine; never he/she dual-gender syntax. Avoid word-for-word translation; prefer phrasing used on Czech psychology pages. Standard Czech grammar, typography, numbers and dates.',
  da: 'Register: informal du. Informal, helpful, engaging yet professional; active voice; clarity over length; avoid noun-heavy formal phrasing. Buttons and CTAs: imperative (Start nu). Help-centre headlines: infinitive. Body-text instructions: imperative. Cite UI elements capitalised without quotation marks even if the source quotes them. Avoid over-using possessive pronouns.',
  de: 'Register: duzen everywhere including emails and legal text; du/dir/dich/dein lowercase except sentence-initial. Generic masculine, no gender star, colon or Binnen-I. Short sentences. Neue Deutsche Rechtschreibung with ss (use the sharp s, not ss). Quotes: German low-high only. Plain spaces and plain hyphens only. Buttons and labels: infinitive. Full CTA sentences and instructions: du-imperative. No final period on labels, buttons or headings; period on full sentences including error messages. Abonnement in all products, never Mitgliedschaft here. Konto not Account. E-Mail. QR-Code hyphenated. Keep English for Dashboard, Support, Upload, Download.',
  el: 'Register: formal 2nd-person plural always. Buttons and CTAs: translate English infinitives as Greek noun forms, not imperatives. Avoid gendered language; default masculine acceptable if rephrasing fails; never dual-gender syntax. Clear friendly tone, no slang. Split long sentences. Final nu: keep on ton and on den; normal rules for min; remove from autin. Dates DD/MM/YYYY, 24-hour HH:MM. Decimal comma, currency symbol after the figure.',
  es: 'Register: informal tu. Clear, direct, professional but simple and natural. Buttons: infinitive. Active voice; colloquial expressions acceptable. Prioritise clarity and naturalness over literal translation. Follow RAE and Fundeu.',
  fr: 'Register: vous unless the source is plainly informal. Clear and concise, never literal; always idiomatic. Exclamation points only occasionally. Aim for gender-neutral epicene phrasing; where addressing the user directly and that fails, add the feminine mark in parentheses. Capitalisation follows French orthography, including the definite-article rule; never carry English title case across. Standard French abbreviations (1er, 1re, 2e, p. ex., etc., Go, h, min, s, M., Mme, Dr).',
  hr: 'Register: formal 2nd-person plural, Vi capitalised when the pronoun is written out. Buttons and CTAs: nouns where natural (Continue as Nastavak, Sign in as Prijava) but avoid verbal nouns; use imperative verbs instead. Unambiguous prompts to the user take 2nd person plural; prompts the user gives the system may take 2nd person singular. Sentence case; do not capitalise nouns mid-sentence. Product names unchanged. Follow pravopis.hr. Rephrase rather than translate word for word.',
  id: 'Register: formal, translate you as Anda at all times, friendly tone. Follow EYD and KBBI. Effective and concise, natural flow. Headings and buttons: noun or verb form, following the source style. Decimal comma, thousand period (3,5 m and 6.000 km). Dates DD/MM/YYYY, 24-hour clock with a dot separator.',
  it: 'Register: informal tu. Friendly, inclusive, respectful, optimistic. CTAs and buttons: imperative (Registrati ora, Accedi). Avoid long sentences and repetition. Prefer phrasing that works for both genders; where impossible use the informato/a form. Never translate URLs. Dates DD/MM/YY, Italian abbreviations (min., sec.). Currency localised as 29,99 with the symbol after. Accented capitals always (E with grave, never E apostrophe). High double quotes; move the period outside the quotes.',
  ko: 'Register: friendly but polite. Declaratives take the -seyo form, questions the -nikka form. Concise, no redundancy. CTA buttons: use the noun form, not -hagi. Avoid second-person address; where unavoidable use the formal honorific. Sentences end with a period; convert a source colon to a period; no periods in titles or headings. Metric units, no space between number and unit. Dates YYYY/MM/DD, 12-hour clock with the Korean AM/PM markers.',
  ms: 'Register: friendly, not overly formal except in legal contexts; inclusive, respectful, optimistic. Follow DBP references (Tatabahasa Dewan, PRPM, Gaya Dewan). Pronouns are gender-neutral. Avoid unnecessary plural marking unless context requires it. CTA buttons: imperative verbs without suffixes.',
  nl: 'Register: informal you (jij/je); warm, welcoming, engaging, informal but still professional, like friendly self-care advice. Follow Van Dale and Woordenlijst.org for spelling. Paraphrasing permitted for style provided register and meaning hold. CTAs: imperative (Klik nu hier). Buttons: infinitive (Resultaten bekijken).',
  no: 'Register: informal du. Informal, helpful, engaging yet professional; active voice; clarity over length; avoid noun-heavy formal phrasing. Buttons and CTAs: imperative (Start na, Les mer). Help-centre headlines: infinitive. Body-text instructions: imperative. Cite UI elements capitalised without quotation marks. Avoid over-using possessive pronouns. Exclamation points and superlatives sparingly.',
  pl: 'Register: 2nd person singular. Gender-neutral forms where possible (Popelniono trzy bledy, not Popelniles). Avoid English passive voice; make the actor the subject. Polish quotation marks (low-high). En dash, not a hyphen, for ranges. Decimal comma. Ordinals take a period after the number. Do not copy English capitalisation in UI names; sentence case. Exclamation marks sparingly.',
  pt: 'Brazilian Portuguese. Register: formal but friendly, confident, helpful, authoritative, science-based. Dates dd/mm/yyyy, long form as day de month de year. 24-hour clock written as 23h30, no spaces, no leading zeros. Space between number and unit; do not pluralise unit symbols. Metric only. Currency real, symbol R$, format R$ 1,10. Decimal comma, thousand period.',
  ro: 'Register: informal tu. Informal, engaging, friendly, approachable; active voice. Gender-neutral phrasing; avoid unnecessary gendered forms. Natural everyday Romanian where appropriate. Buttons and CTAs: clear direct imperative verbs. Borrowed words take -uri without a hyphen (feedbackul); acronyms and foreign terms with non-standard endings take a hyphen (PDF-uri). Check DOOM and DEX for plurals and definite forms.',
  sk: 'Register: formal vy throughout (vy, vas, vasa, vam, vase). Capitalise V only in personalised emails and messages, never in general website copy. Space between number and unit (500 KB); space as thousand separator over four digits (1 500); true minus sign for negatives. Currency after the amount (35 EUR sign). Sentence case always, even where the source uses title case. Accented capitals. Gender-neutral rephrasing where the source has a singular pronoun or participle.',
  sv: 'Register: informal du, never the singular ni. Informal, helpful, engaging yet professional; active voice; clarity over length; avoid noun-heavy formal phrasing. Buttons and CTAs: imperative (Starta nu, Las mer). Help-centre headlines: infinitive. Body-text instructions: imperative. Cite UI elements capitalised without quotation marks. Avoid over-using possessive pronouns. Exclamation points and superlatives sparingly. Gender-neutral vocabulary where available.',
  th: 'Thai per the reviewed guide of 1 Sep 2026. No spaces between words; use spaces only where Thai convention requires a phrase break. No sentence-final period. Arabic numerals. Latin script only for brand names and placeholders, never for translated content. Neutral polite register; avoid the sentence-final politeness particles in UI copy. Do not translate placeholder names or HTML tags.',
  tr: 'Register: 2nd person plural polite for body copy and CTA links (Buraya tiklayin), but avoid the over-formal -iniz form. Buttons: 2nd person singular (Giris yap, Teste basla). Currency as a code to the right of the figure with a space (10 USD, 25 GBP), never a symbol on the left. Turkish decimal and thousand separators (10.000 for 10,000; percent written before the figure with a comma decimal). Times use a full stop, not a colon (13.35). Follow TDK for spelling and punctuation.',
  uk: 'Register: formal Vy, gender-neutral language. Friendly tone; avoid overly formal pronoun-heavy phrasing; avoid repetition. Restructure the English sentence so it reads naturally in Ukrainian. CTAs: imperative. Ordinary buttons: infinitive. Punctuation: guillemets for quotes, em dash, curly apostrophe. Respect character limits, staying near the source length.',
  vi: 'Sentence case in general; exception for widely used organisation names. Avoid passive voice. Double quotes even where the source uses single. No comma before va or hoac. No hyphens splitting words. Decimal comma, thousand full stop. 24-hour clock preferred. No space before a full stop, and none inside brackets.'
};

// Exclusions established from the 7 Sep backlog probe: every untranslated key in these
// projects was archived, tagged to_exclude, or had an empty EN source.
const EXCLUDE_TAGS = ['to_exclude'];

return [{ json: { DRY_RUN, MAX_UNITS_PER_FIRE, MODEL, TM_TTL_MS, GLOSSARY_PID, PROJECTS, LANGS, GUIDES, EXCLUDE_TAGS } }];

const c = $('Config').first().json;
const ev = $('Lokalise Event').first().json || {};
const b = ev.body || ev;
const store = $getWorkflowStaticData('global');
if (!store.seen) { store.seen = {}; }

const pid = String(b.project && b.project.id ? b.project.id : (b.project_id || ''));
const type = String(b.event || b.event_type || '');
const project = c.PROJECTS[pid];
const drop = [];

if (!project) { drop.push('project not in scope: ' + pid); }

// Only the events a Lokalise automation would fire on: a new key, or an EN source edit.
const KEY_EVENTS = ['project.key.added', 'project.keys.added'];
const TRANS_EVENTS = ['project.translation.updated', 'project.translations.updated'];
let ids = [];
if (KEY_EVENTS.indexOf(type) !== -1) {
  const arr = b.keys || (b.key ? [b.key] : []);
  for (const k of arr) { if (k && (k.id || k.key_id)) { ids.push(Number(k.id || k.key_id)); } }
} else if (TRANS_EVENTS.indexOf(type) !== -1) {
  const arr = b.translations || (b.translation ? [b.translation] : []);
  for (const t of arr) {
    const iso = String((t.language && t.language.iso) || t.language_iso || '');
    if (iso !== 'en') { continue; }   // only EN source edits retrigger a fill
    if (t.key && (t.key.id || t.key_id)) { ids.push(Number(t.key.id || t.key_id)); }
    else if (t.key_id) { ids.push(Number(t.key_id)); }
  }
  if (!ids.length) { drop.push('translation event with no EN key ids'); }
} else {
  drop.push('event type not handled: ' + type);
}

// Dedupe: a key already processed for this project is not refilled.
const fresh = [];
for (const id of ids) {
  const tag = pid + ':' + id;
  if (store.seen[tag]) { continue; }
  fresh.push(id);
}
const capped = fresh.slice(0, c.MAX_UNITS_PER_FIRE);
const deferred = fresh.length - capped.length;

return [{ json: {
  has_work: capped.length > 0 && !!project,
  pid: pid,
  project_name: project ? project.name : null,
  event: type,
  key_ids: capped,
  deferred: deferred,
  dropped: drop
} }];

const c = $('Config').first().json;
const w = $('Normalize Event').first().json;
const B = 'https://api.lokalise.com/api2';
const out = [];

// the affected keys themselves
out.push({ json: { kind: 'keys', pid: w.pid, url: B + '/projects/' + w.pid + '/keys?filter_key_ids=' + w.key_ids.join(',') + '&include_translations=1&limit=200' } });

// the shared glossary, cursor-paginated (page= silently re-serves page 1)
out.push({ json: { kind: 'glossary', pid: c.GLOSSARY_PID, url: B + '/projects/' + c.GLOSSARY_PID + '/glossary-terms?limit=500' } });

// TM corpus, only when the cached index is stale. limit=200 because 500 crashes above ~5k keys.
const store = $getWorkflowStaticData('global');
const stale = !store.tm_built_at || (Date.now() - store.tm_built_at) > c.TM_TTL_MS;
if (stale) {
  for (const p of Object.keys(c.PROJECTS)) {
    for (let pg = 1; pg <= 12; pg++) {
      out.push({ json: { kind: 'tm', pid: p, page: pg, url: B + '/projects/' + p + '/keys?include_translations=1&limit=200&page=' + pg } });
    }
  }
}
return out;

const c = $('Config').first().json;
const w = $('Normalize Event').first().json;
const reqs = $('Build Fetch Plan').all();
const res = $input.all();
const store = $getWorkflowStaticData('global');

const norm = function (s) { return String(s == null ? '' : s).replace(/\s+/g, ' ').trim().toLowerCase(); };
const txt = function (t) {
  if (t == null) { return ''; }
  if (typeof t === 'object') { return ''; }   // plural objects handled separately, skipped here
  return String(t);
};

let targetKeys = [];
const glossary = [];
let tmPages = 0;
const tm = (store.tm && !((!store.tm_built_at) || (Date.now() - store.tm_built_at) > c.TM_TTL_MS)) ? store.tm : {};
const rebuilding = Object.keys(tm).length === 0;

for (let i = 0; i < res.length; i++) {
  const meta = (reqs[i] || { json: {} }).json;
  const r = res[i].json || {};
  const b = r.body || {};
  if (meta.kind === 'keys') {
    if (!Array.isArray(b.keys)) { throw new Error('keys fetch returned no array - aborting rather than filling blind'); }
    targetKeys = b.keys;
  } else if (meta.kind === 'glossary') {
    for (const t of (b.data || [])) { if (t.translatable) { glossary.push(t); } }
  } else if (meta.kind === 'tm') {
    if (!Array.isArray(b.keys)) { continue; }
    tmPages++;
    for (const k of b.keys) {
      if (k.is_archived) { continue; }
      let en = '';
      const per = {};
      for (const t of (k.translations || [])) {
        const s = txt(t.translation);
        if (!s.trim()) { continue; }
        if (t.language_iso === 'en') { en = s; continue; }
        // TM only trusts reviewed, non-fuzzy strings
        if (t.is_reviewed && !t.is_fuzzy && !t.is_unverified) { per[t.language_iso] = s; }
      }
      if (!en.trim()) { continue; }
      const key = norm(en);
      if (!tm[key]) { tm[key] = {}; }
      for (const iso of Object.keys(per)) {
        if (tm[key][iso] === undefined) { tm[key][iso] = per[iso]; }
        else if (tm[key][iso] !== per[iso]) { tm[key][iso] = null; }   // ambiguous - never used
      }
    }
  }
}
if (rebuilding && tmPages > 0) { store.tm = tm; store.tm_built_at = Date.now(); }

const langs = c.LANGS[w.pid] || {};
const tmHits = [];
const aiUnits = [];
const skipped = [];

for (const k of targetKeys) {
  const name = (k.key_name || {}).web || (k.key_name || {}).other || '';
  if (k.is_archived) { skipped.push({ key: name, why: 'archived' }); continue; }
  if (k.is_hidden) { skipped.push({ key: name, why: 'hidden' }); continue; }
  const tags = k.tags || [];
  let excluded = false;
  for (const t of c.EXCLUDE_TAGS) { if (tags.indexOf(t) !== -1) { excluded = true; } }
  if (excluded) { skipped.push({ key: name, why: 'tagged to_exclude' }); continue; }
  if (k.is_plural) { skipped.push({ key: name, why: 'plural - not handled in v1' }); continue; }

  let en = '';
  const empty = [];
  for (const t of (k.translations || [])) {
    const s = txt(t.translation);
    if (t.language_iso === 'en') { en = s; continue; }
    if (langs[t.language_iso] === undefined) { continue; }
    if (!s.trim()) { empty.push(t.language_iso); }
  }
  if (!en.trim()) { skipped.push({ key: name, why: 'empty EN source' }); continue; }
  if (!empty.length) { skipped.push({ key: name, why: 'nothing empty' }); continue; }

  const hit = tm[norm(en)] || {};
  const gslice = [];
  for (const g of glossary) {
    let term = '';
    for (const tr of (g.translations || [])) { if (tr.langIso === 'en' || tr.langId === 640) { term = tr.translation; } }
    if (!term) { term = g.term || ''; }
    if (!term) { continue; }
    if (norm(en).indexOf(norm(term)) === -1) { continue; }
    gslice.push(g);
  }

  for (const iso of empty) {
    const cand = hit[iso];
    if (cand) {
      tmHits.push({ key_id: k.key_id, key: name, iso: iso, lang_id: langs[iso], text: cand, en: en });
    } else {
      const terms = [];
      for (const g of gslice) {
        for (const tr of (g.translations || [])) {
          if (tr.langIso === iso && tr.translation) { terms.push((g.term || '') + ' = ' + tr.translation); }
        }
      }
      aiUnits.push({ key_id: k.key_id, key: name, iso: iso, lang_id: langs[iso], en: en,
        guide: c.GUIDES[iso] || '', glossary: terms.slice(0, 25), description: k.description || '', char_limit: k.char_limit || 0 });
    }
  }
}

return [{ json: { pid: w.pid, project_name: w.project_name, tm_hits: tmHits, ai_units: aiUnits, skipped: skipped,
  tm_index_size: Object.keys(tm).length, tm_rebuilt: rebuilding && tmPages > 0, deferred: w.deferred } }];

const c = $('Config').first().json;
const p = $('Plan Units').first().json;
const out = [];
for (const u of p.ai_units) {
  const sys = 'You are a professional localisation translator working into ' + u.iso + '. Translate the English UI string exactly, obeying the style guide. Output ONLY the translation, no quotes, no commentary, no explanation. Preserve every placeholder, HTML tag and attribute unchanged, including surrounding spaces and punctuation. Never translate placeholder names or brand names. Preserve leading and trailing whitespace exactly as in the source. Match the source terminal punctuation: if the source ends with a full stop, so does your output; if it does not, yours must not either.';
  let usr = 'STYLE GUIDE for ' + u.iso + ':\n' + u.guide + '\n\n';
  if (u.glossary.length) { usr += 'GLOSSARY - these renderings are mandatory and override the style guide:\n' + u.glossary.join('\n') + '\n\n'; }
  if (u.description) { usr += 'CONTEXT for this string: ' + u.description + '\n\n'; }
  if (u.char_limit) { usr += 'HARD CHARACTER LIMIT: ' + u.char_limit + '\n\n'; }
  usr += 'KEY NAME (for context only, do not translate): ' + u.key + '\n\nENGLISH SOURCE:\n' + u.en;
  out.push({ json: { unit: u, body: { model: c.MODEL, max_tokens: 1000, temperature: 0.2,
    messages: [ { role: 'system', content: sys }, { role: 'user', content: usr } ] } } });
}
if (!out.length) { return [{ json: { unit: null, body: null, nothing_to_generate: true } }]; }
return out;

const c = $('Config').first().json;
const p = $('Plan Units').first().json;
const reqs = $('Build AI Requests').all();
const res = $input.all();
const proj = c.PROJECTS[p.pid];

const rejected = [];
const accepted = [];

const LATIN = /[A-Za-z]/;
const stripQ = function (s) { return s.replace(/["\u201c\u201d\u00ab\u00bb\u201e\u2018\u2019']+$/, ''); };
const endPunct = function (s) { const t = stripQ(s.trim()); const ch = t.slice(-1); return /[.!?:;]/.test(ch) ? ch : ''; };
const tags = function (s) { const m = String(s).match(/<[^>]+>/g) || []; return m.slice().sort().join('|'); };
const phold = function (s) { const m = String(s).match(/\[%[^\]]+\]|\{\{?[^}]+\}?\}|%[sd@]|%\d+\$[sd@]/g) || []; return m.slice().sort().join('|'); };

for (let i = 0; i < res.length; i++) {
  const meta = (reqs[i] || { json: {} }).json;
  if (!meta || !meta.unit) { continue; }
  const u = meta.unit;
  const r = res[i].json || {};
  if (r.statusCode !== 200) { rejected.push({ key: u.key, iso: u.iso, why: 'model HTTP ' + r.statusCode }); continue; }
  const body = r.body || {};
  let outText = '';
  try { outText = body.choices[0].message.content; } catch (e) { outText = ''; }
  if (!outText || !String(outText).trim()) { rejected.push({ key: u.key, iso: u.iso, why: 'empty model output' }); continue; }
  let t = String(outText);

  // strip a wrapping quote pair the model sometimes adds
  if (/^".*"$/.test(t.trim()) && !/^".*"$/.test(u.en.trim())) { t = t.trim().slice(1, -1); }

  // whitespace repair rather than rejection
  const lead = (u.en.match(/^\s*/) || [''])[0];
  const trail = (u.en.match(/\s*$/) || [''])[0];
  t = lead + t.trim() + trail;

  // markup and placeholder fidelity - hard reject
  if (tags(t) !== tags(u.en)) { rejected.push({ key: u.key, iso: u.iso, why: 'HTML tag signature changed' }); continue; }
  if (phold(t) !== phold(u.en)) { rejected.push({ key: u.key, iso: u.iso, why: 'placeholder signature changed' }); continue; }

  // untranslated passthrough, only for multi-word sources so single-word loanwords survive
  const multi = u.en.trim().split(/\s+/).length > 1;
  if (multi && t.trim().toLowerCase() === u.en.trim().toLowerCase()) { rejected.push({ key: u.key, iso: u.iso, why: 'model returned the source unchanged' }); continue; }

  // Thai must not come back in Latin script
  if (u.iso === 'th' && LATIN.test(t.replace(/<[^>]+>/g, '').replace(/\[%[^\]]+\]/g, ''))) {
    rejected.push({ key: u.key, iso: u.iso, why: 'Latin script in Thai output' }); continue;
  }

  // terminal punctuation parity, Thai exempt because it takes no sentence-final period
  if (u.iso !== 'th' && endPunct(t) !== endPunct(u.en)) {
    rejected.push({ key: u.key, iso: u.iso, why: 'terminal punctuation differs from source' }); continue;
  }

  if (u.char_limit && t.length > u.char_limit) { rejected.push({ key: u.key, iso: u.iso, why: 'over char limit ' + u.char_limit }); continue; }

  accepted.push({ key_id: u.key_id, key: u.key, iso: u.iso, lang_id: u.lang_id, text: t, kind: 'ai' });
}

for (const h of p.tm_hits) { accepted.push({ key_id: h.key_id, key: h.key, iso: h.iso, lang_id: h.lang_id, text: h.text, kind: 'tm' }); }

// CRITICAL: bulk PUT /keys keeps only ONE translations array per key_id. Sending the same
// key twice for different locales makes the second silently vanish with HTTP 200.
// So every locale for a key must be grouped under a single key entry.
const byKey = {};
for (const a of accepted) {
  if (!byKey[a.key_id]) { byKey[a.key_id] = []; }
  byKey[a.key_id].push({
    language_iso: a.iso,
    translation: a.text,
    is_fuzzy: a.kind === 'ai',
    is_reviewed: false,
    custom_translation_status_ids: [ a.kind === 'tm' ? proj.tm : proj.ai ]
  });
}
const keys = [];
for (const kid of Object.keys(byKey)) { keys.push({ key_id: Number(kid), translations: byKey[kid] }); }

const tmCount = accepted.filter(function (a) { return a.kind === 'tm'; }).length;
const aiCount = accepted.filter(function (a) { return a.kind === 'ai'; }).length;

return [{ json: {
  pid: p.pid, project_name: p.project_name, dry_run: c.DRY_RUN,
  url: 'https://api.lokalise.com/api2/projects/' + p.pid + '/keys',
  payload: { keys: keys },
  will_write: keys.length > 0 && !c.DRY_RUN,
  counts: { tm: tmCount, ai: aiCount, keys: keys.length, rejected: rejected.length, skipped: p.skipped.length },
  rejected: rejected, skipped: p.skipped, accepted: accepted,
  tm_index_size: p.tm_index_size, tm_rebuilt: p.tm_rebuilt, deferred: p.deferred
} }];

const g = $('Gate And Group').first().json;
const r = $input.first().json || {};
const store = $getWorkflowStaticData('global');
if (!store.seen) { store.seen = {}; }

const confirmed = [];
const mismatched = [];
if (g.will_write && r.statusCode === 200) {
  const back = {};
  for (const k of ((r.body || {}).keys || [])) {
    for (const t of (k.translations || [])) { back[k.key_id + ':' + t.language_iso] = t.translation; }
  }
  for (const a of g.accepted) {
    const got = back[a.key_id + ':' + a.iso];
    if (got === a.text) { confirmed.push(a.key + ' [' + a.iso + ']'); }
    else { mismatched.push({ key: a.key, iso: a.iso, sent: a.text, echoed: got === undefined ? '(absent)' : got }); }
  }
  // only mark a key seen once its write was echoed back correctly
  for (const a of g.accepted) {
    if (back[a.key_id + ':' + a.iso] === a.text) { store.seen[g.pid + ':' + a.key_id] = Date.now(); }
  }
}

return [{ json: {
  project: g.project_name,
  dry_run: g.dry_run,
  wrote: !!g.will_write,
  http: r.statusCode === undefined ? null : r.statusCode,
  counts: g.counts,
  confirmed: confirmed.length,
  mismatched: mismatched,
  rejected: g.rejected,
  skipped: g.skipped,
  tm_index_size: g.tm_index_size,
  tm_rebuilt: g.tm_rebuilt,
  deferred_to_next_fire: g.deferred,
  rollback_hint: 'to revert, set the listed key/locale pairs back to empty string'
} }];
